// 5件の記事（タイトル＋リンク）を、AIに渡す1つのテキストにまとめる（動画Step4の後半＝下ごしらえ）
const items = $input.all();
const articles = items.map((it, i) => {
  const t = it.json.title || '';
  const l = it.json.link || '';
  return `${i + 1}. ${t}\n${l}`;
}).join('\n');
return [{ json: { articles, count: items.length } }];

// Geminiの返答テキストを取り出す（ノード構成で入る場所が違うため複数候補を見る）
let raw = $json.content?.parts?.[0]?.text ?? $json.candidates?.[0]?.content?.parts?.[0]?.text ?? $json.text ?? $json.response ?? $json.output ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.replace(/```/g, '').trim();
const today = new Date();
const dateStr = `${today.getFullYear()}/${today.getMonth() + 1}/${today.getDate()}`;
const summary = `:newspaper: *今朝のニュース3行要約（${dateStr}）*\n${raw}`;
return [{ json: { summary } }];
